#!/usr/bin/env python3
"""Fixed metadata-only observation, existing owner repair entry."""
import base64,gzip,hashlib,json,os,re,sys,types
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='6475cc92b8c3154ed46a13abbcd16b88b6fe1ee87717ac33cb1bf7ab31d94bbc':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('asset_metadata');m.__file__='<reviewed-asset_metadata>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='8c34141eff0ee0cfeaf5f42373781da4246f3aa19bce506614d7056725c695d6':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('cpu_service_binding_diagnostic');m.__file__='<reviewed-cpu_service_binding_diagnostic>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
request=os.environ.get('NOX_OWNER_REQUEST_ID','')
source=os.environ.get('NOX_OWNER_SOURCE_SHA','')
context=bool(os.geteuid()==0 and re.fullmatch(r'[0-9]{1,24}',request) and re.fullmatch(r'[0-9a-f]{40}',source))
report={'schema':'NOX_PREFLIGHT_METADATA_OBSERVATION_V1','request':request if context else None,'source_sha':source if context else None,'accepted':False,'used':False,'application_mutations':0,'model_calls':0,'raw_secrets_exported':False}
if context:
    report['asset_ancestors']=sys.modules['asset_metadata'].observe_asset_ancestors()
    report['v120_source']=sys.modules['asset_metadata'].observe_v120_source_metadata()
    report['dispatcher_service']=sys.modules['cpu_service_binding_diagnostic'].observe()
    report['status']='OBSERVED_NOT_ACCEPTANCE'
else: report['status']='HOLD_OWNER_CONTEXT'
print('NOX_MAINT_REPAIR='+json.dumps({'kind':'fixed_preflight_metadata','data':report},separators=(',',':')),flush=True)
print('NOX_MAINT_REPAIR_COMPLETE='+str(context).lower(),flush=True)
raise SystemExit(0 if context else 2)
